DELETE FROM public.analyses WHERE user_id IS NULL;ALTER TABLE public.analyses ALTER COLUMN user_id SET NOT NULL;ALTER TABLE public.analyses ADD CONSTRAINT analyses_user_id_fkey FOREIGN KEY(user_id) REFERENCES auth.users(id) ON DELETE CASCADE;CREATE INDEX IF NOT EXISTS analyses_user_id_created_at_idx ON public.analyses(user_id,created_at DESC);GRANT SELECT,INSERT,DELETE ON public.analyses TO authenticated;GRANT ALL ON public.analyses TO service_role;ALTER TABLE public.analyses ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS "Users can view their own analyses" ON public.analyses;CREATE POLICY "Users can view their own analyses" ON public.analyses FOR SELECT TO authenticated USING(auth.uid()=user_id);DROP POLICY IF EXISTS "Users can create their own analyses" ON public.analyses;CREATE POLICY "Users can create their own analyses" ON public.analyses FOR INSERT TO authenticated WITH CHECK(auth.uid()=user_id);DROP POLICY IF EXISTS "Users can delete their own analyses" ON public.analyses;CREATE POLICY "Users can delete their own analyses" ON public.analyses FOR DELETE TO authenticated USING(auth.uid()=user_id);
